using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;using ProMaxx2.QA.Domain.Projects;using ProMaxx2.QA.Domain.TestManagement;
namespace ProMaxx2.QA.Infrastructure.Persistence;
public sealed class TestSuiteConfiguration:IEntityTypeConfiguration<TestSuite>{public void Configure(EntityTypeBuilder<TestSuite>b){b.ToTable("TestSuites");b.HasKey(x=>x.TestSuiteId);b.Property(x=>x.TestSuiteId).HasDefaultValueSql("NEWSEQUENTIALID()");b.Property(x=>x.SuiteCode).HasMaxLength(100).IsRequired();b.Property(x=>x.SuiteName).HasMaxLength(200).IsRequired();b.Property(x=>x.SuiteType).HasMaxLength(50);b.Property(x=>x.RiskTier).HasMaxLength(20);b.HasIndex(x=>new{x.ProjectId,x.SuiteCode}).IsUnique();b.HasOne<Project>().WithMany().HasForeignKey(x=>x.ProjectId).OnDelete(DeleteBehavior.Restrict);}}
public sealed class TestSuiteCaseConfiguration:IEntityTypeConfiguration<TestSuiteCase>{public void Configure(EntityTypeBuilder<TestSuiteCase>b){b.ToTable("TestSuiteCases");b.HasKey(x=>new{x.TestSuiteId,x.TestCaseId});b.HasOne(x=>x.Suite).WithMany(x=>x.Cases).HasForeignKey(x=>x.TestSuiteId).OnDelete(DeleteBehavior.Cascade);b.HasOne(x=>x.TestCase).WithMany().HasForeignKey(x=>x.TestCaseId).OnDelete(DeleteBehavior.Restrict);}}
